const listInvoices = `-- name: ListInvoices :many

SELECT id, number, currency, rate_to_bdt, amount, amount_bdt, items, expense_date, description, status, requested_by, requested_by_name, requested_by_role, hr_reviewed_by, hr_reviewed_by_name, hr_reviewed_at, hr_note, ceo_reviewed_by, ceo_reviewed_by_name, ceo_reviewed_at, ceo_note, ledger_lines, created_at, updated_at FROM invoice_details
WHERE ($1::text[] IS NULL OR status = ANY ($1::text[]))
  AND ($2::uuid IS NULL OR requested_by = $2)
  AND ($3::text IS NULL OR expense_date::date >= $3::text::date)
  AND ($4::text IS NULL OR expense_date::date <= $4::text::date)
  -- The search covers what the invoice is for and what is on it.
  AND ($5::text IS NULL OR description ILIKE '%' || $5 || '%'
       OR EXISTS (SELECT 1 FROM invoice_items it WHERE it.invoice_id = invoice_details.id
                    AND it.description ILIKE '%' || $5 || '%'))
ORDER BY expense_date::date DESC, number DESC
LIMIT 500
`

